(()=>{'use strict';
const $=s=>document.querySelector(s),main=$('#main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TOPICS={ponteiros:'Ponteiros',funcoes:'Funções e recursão',arquivos:'Arquivos',vetores:'Vetores',strings:'Strings',matrizes:'Matrizes',structs:'Estruturas',np1:'Base da NP1'};
const KEY='c-em-pratica-np2-v1';
const empty=()=>({version:1,lessons:{},answers:{},errors:{},labs:{},drafts:{},notes:{},cards:{},plan:{},days:7,theme:'light',history:[],session:null});
let S=empty(),storageOK=true;
try{S={...S,...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch{storageOK=false;}$('#save-status').textContent=storageOK?'Progresso salvo neste navegador':'Armazenamento indisponível. Exporte seu progresso.';}
document.body.classList.toggle('dark',S.theme==='dark');
$('#theme').onclick=()=>{S.theme=S.theme==='dark'?'light':'dark';document.body.classList.toggle('dark',S.theme==='dark');save();};
const Q=window.QUESTIONS,L=window.LESSONS,B=window.LABS;
const navs=[['inicio','⌂','Visão geral'],['trilha','▤','Trilha de estudo'],['laboratorio','⌘','Laboratório de C'],['visualizar','◇','Entenda visualmente'],['treino','◎','Treino de questões'],['simulados','◷','Simulados'],['revisao','↻','Revisão e erros'],['plano','✓','Plano de estudo'],['referencia','≡','Consulta rápida']];
$('#nav').innerHTML=navs.map(([id,icon,label])=>`<a href="#${id}" data-nav="${id}"><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('');
const btn=(label,action,arg='',cls='')=>`<button class="btn ${cls}" data-action="${action}" data-arg="${esc(arg)}">${label}</button>`;
const link=(label,path,cls='')=>`<a class="btn ${cls}" href="#${path}">${label}</a>`;
const pre=code=>`<pre><code>${esc(code)}</code></pre>`;
const heading=(eyebrow,title,desc='')=>`<div class="page-head"><div class="eyebrow muted">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`;
const tag=t=>`<span class="tag">${esc(t)}</span>`;
function toast(t){const el=$('#toast');el.textContent=t;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4000);}
function go(p){if(location.hash==='#'+p)render();else location.hash=p;}
function random(arr){return [...arr].sort(()=>Math.random()-.5);}
const pct=(n,d)=>d?Math.round(100*n/d):0;
function statTopic(topic){const qs=Q.filter(q=>q.topic===topic),done=qs.filter(q=>S.answers[q.id]),right=done.filter(q=>S.answers[q.id].correct);return{total:qs.length,done:done.length,right:right.length,rate:pct(right.length,done.length)};}
const doneLessons=()=>L.filter(l=>S.lessons[l.id]).length;
const doneLabs=()=>B.filter(b=>S.labs[b.id]?.passed).length;
function dashboard(){
const answers=Object.values(S.answers),right=answers.filter(a=>a.correct).length,next=L.find(l=>!S.lessons[l.id])||L[0];
main.innerHTML=`<div class="hero"><div><div class="eyebrow">DA TEORIA PARA O CÓDIGO</div><h1>Entender C.<br>Praticar de verdade.</h1><p>Seu caminho até a NP2: pense no que o programa faz, escreva sua solução e aprenda com cada tentativa.</p><div class="row">${btn(answers.length?'Continuar meu estudo →':'Começar diagnóstico →',answers.length?'lesson':'start',answers.length?next.id:'diagnostic','primary')}${link('Explorar a trilha','trilha','ghost')}</div><p class="note" style="margin:16px 0 0">${L.length} aulas · ${Q.length} questões comentadas · ${B.length} desafios em C</p></div><div class="hero-art" aria-label="Ponteiro p aponta para x. Alterar *p muda x."><div class="memory-art"><span class="eyebrow muted">DO ENDEREÇO AO VALOR</span>${pre('int x = 10;\nint *p = &x;\n*p = 75;')}<div class="memory-cells"><span><em>ponteiro p</em><b>&amp;x</b></span><strong>→</strong><span><em>variável x</em><b>75</b></span></div><small class="muted">Um endereço. Uma mudança real.</small></div></div></div>
<div class="stats"><div class="stat"><b>${doneLessons()}<small> / ${L.length}</small></b><span>Aulas marcadas como estudadas</span></div><div class="stat"><b>${answers.length}<small> / ${Q.length}</small></b><span>Questões praticadas</span></div><div class="stat"><b>${answers.length?pct(right,answers.length)+'%':'—'}</b><span>Acerto na última tentativa por questão</span></div><div class="stat"><b>${doneLabs()}<small> / ${B.length}</small></b><span>Desafios com testes aprovados</span></div></div>
<div class="grid two"><section class="card"><div class="row between"><h2>Seu próximo passo</h2>${tag('TRILHA GUIADA')}</div><p>${esc(next.summary)}</p><h3>${esc(next.title)}</h3><div class="row">${link('Abrir aula →','trilha/'+next.id,'primary')}<span class="note">≈ ${next.minutes} min · PDF p. ${next.page}</span></div></section><section class="card"><h2>Faça uma sessão completa</h2><p>Leia uma aula, tente um desafio sem olhar a solução e resolva 5 questões do tema. Termine explicando um erro com suas palavras.</p><div class="row">${link('Abrir laboratório','laboratorio')}${link('Meu caderno de erros ('+Object.keys(S.errors).length+')','revisao')}</div></section></div>
<div class="row between section-heading"><h2>O que você precisa dominar</h2><span class="note">Prioridades orientadas pelo PDF</span></div><div class="card">${Object.entries(TOPICS).map(([id,title],i)=>{const st=statTopic(id);return `<div class="course-row"><span class="course-number">0${i+1}</span><div><h3>${title}</h3><p>${st.done?`${st.right} de ${st.done} questões corretas na última tentativa`:'Ainda sem tentativas registradas'} · ${id==='np1'?'Fundamentos que sustentam a NP2':'Conteúdo da NP2'}</p></div>${btn('Praticar →','topic',id,'small')}</div>`;}).join('')}</div><p class="note" style="margin-top:15px">O progresso registra sua prática; não prevê a nota da prova. Os simulados seguem o estilo do material, que não contém uma prova anterior confirmada.</p>`;
}
function lessons(id){const lesson=L.find(l=>l.id===id);
if(!lesson){main.innerHTML=heading('SEU CAMINHO','Aprenda um conceito. Use no próximo.','Comece pela base se estiver enferrujado. As aulas ficam abertas para você seguir a ordem que precisar.')+`<div class="grid two">${L.map((l,i)=>`<article class="card"><div class="row between"><span class="eyebrow muted">${String(i+1).padStart(2,'0')} · ${TOPICS[l.topic]}</span>${S.lessons[l.id]?tag('ESTUDADA'):''}</div><h3 style="margin-top:14px">${esc(l.title)}</h3><p>${esc(l.summary)}</p><div class="row between"><span class="note">≈ ${l.minutes} min · PDF p. ${l.page}</span>${link('Estudar →','trilha/'+l.id,'small')}</div></article>`).join('')}</div>`;return;}
const index=L.indexOf(lesson);main.innerHTML=`<div class="row between" style="margin-bottom:24px">${link('← Todas as aulas','trilha','ghost')}<span class="note">Aula ${index+1} de ${L.length} · PDF p. ${lesson.page}</span></div><div class="lesson-layout"><div class="lesson-list">${L.map((l,i)=>`<button class="${l.id===id?'active':''}" data-action="lesson" data-arg="${l.id}">${S.lessons[l.id]?'✓ ':String(i+1).padStart(2,'0')+' '}${esc(l.title)}</button>`).join('')}</div><article class="lesson-content">${heading(TOPICS[lesson.topic],esc(lesson.title),esc(lesson.summary))}<div class="objectives"><strong>Ao terminar, você deve conseguir:</strong><ul>${lesson.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div>${lesson.sections.map(s=>`<section><h2>${esc(s.heading)}</h2><p>${esc(s.body)}</p>${s.code?pre(s.code):''}</section>`).join('')}<div class="callout warn"><strong>Atenção à pegadinha</strong><p>${esc(lesson.pitfall)}</p></div><section class="card"><div class="eyebrow muted">LEMBRAR SEM CONSULTAR</div><h3 style="margin-top:12px">${esc(lesson.recall.prompt)}</h3><label class="form-field"><span class="note">Escreva sua explicação antes de abrir a resposta.</span><textarea rows="3" data-note="${id}" placeholder="Explique com suas palavras…">${esc(S.notes[id]||'')}</textarea></label><details><summary>Conferir a ideia central</summary><p>${esc(lesson.recall.answer)}</p></details><p class="note">Sua explicação fica salva para revisão. Não há correção automática deste texto.</p></section><div class="row" style="margin:24px 0">${btn(S.lessons[id]?'✓ Aula estudada':'Marcar como estudada','completeLesson',id,'primary')}${btn('Treinar este assunto','topic',lesson.topic)}${link('Praticar com código','laboratorio/'+(B.find(b=>b.topic===lesson.topic)?.id||B[0].id))}</div><div class="row between">${index?link('← Aula anterior','trilha/'+L[index-1].id,'ghost'):'<span></span>'}${index<L.length-1?link('Próxima aula →','trilha/'+L[index+1].id,'ghost'):link('Fazer um simulado →','simulados')}</div></article></div>`;
}
let activeLab=null,worker=null,pending=null,workerTimer,runBusy=false;
function laboratory(id){const b=B.find(x=>x.id===id);
if(!b){main.innerHTML=heading('PENSE · ESCREVA · EXECUTE','Seu laboratório de C','Escreva programas reais. Os testes comparam saídas e arquivos; use também os critérios de autocorreção para avaliar a lógica da sua solução.')+`<div class="callout"><p><strong>Como funciona:</strong> preencha a entrada do programa antes de executar. O compilador é carregado na primeira execução (aproximadamente 53 MB; internet necessária). Depois, os programas rodam no navegador.</p><p class="note">Arquivos são virtuais e recomeçam a cada execução. Neste laboratório, use caminhos como /dados.txt. Os recursos de Windows, como conio.h e system("pause"), não estão disponíveis.</p></div><div class="grid two">${B.map(b=>`<article class="card"><div class="row between">${tag(b.level)}${S.labs[b.id]?.passed?tag(S.labs[b.id].assisted?'✓ COM CONSULTA':'✓ TESTES OK'):''}</div><h3 style="margin-top:16px">${esc(b.title)}</h3><p>${esc(b.prompt)}</p><div class="row between"><span class="note">${TOPICS[b.topic]} · PDF p. ${b.page}</span>${link('Resolver →','laboratorio/'+b.id,'small')}</div></article>`).join('')}</div>`;return;}
activeLab=b;const draft=S.drafts[b.id]||{};
main.innerHTML=`<div class="row between" style="margin-bottom:20px">${link('← Todos os desafios','laboratorio','ghost')}${tag(b.level)}</div>${heading(TOPICS[b.topic],esc(b.title),esc(b.prompt))}<div class="lab-layout"><section><div class="row between"><label for="editor"><strong>Seu código · C11</strong></label><span class="note">Rascunho salvo automaticamente</span></div><div class="code-area" style="margin-top:10px"><textarea id="editor" class="code" spellcheck="false" autocapitalize="off" autocomplete="off" aria-label="Editor de código C">${esc(draft.code??b.starter)}</textarea></div><div class="row" style="margin-top:12px">${btn('▶ Executar','run','','primary')}${btn('✓ Verificar testes','test')}${btn('■ Parar','stop','','ghost')}<span id="run-status" class="note" aria-live="polite">Pronto para começar</span></div><div class="row" style="margin-top:12px">${btn('Baixar .c','downloadCode','','small ghost')}${btn('Restaurar início','restoreCode','','small ghost')}${btn('Nova dica','hint','','small')}</div><div id="hints"></div><details id="solution"><summary>Consultar uma solução possível</summary><p class="note">Tente primeiro. Ao consultar, este desafio fica marcado como prática com apoio.</p>${pre(b.solution)}${btn('Usar solução no editor','useSolution','','small')}</details><details><summary>Critérios para revisar sua lógica</summary><ul>${b.rubric.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><p class="note">Passar nos testes confirma os casos apresentados. Os requisitos de técnica (como usar recursão) precisam ser conferidos por você nos critérios acima.</p></details></section><section class="stack"><div class="card"><div class="form-field"><label for="stdin">Entrada do programa (scanf / fgets)</label><textarea id="stdin" rows="3" placeholder="Digite os dados antes de executar">${esc(draft.stdin??b.stdin)}</textarea></div><p class="note">Use ponto nos decimais. Separe os valores por espaços ou linhas.</p><div class="row between"><strong>Saída</strong><span id="exit-code" class="note"></span></div><pre id="stdout" class="terminal" aria-live="polite"></pre><div id="compiler-help"></div><details id="diagnostics" hidden><summary>Mensagens do compilador</summary><pre id="stderr"></pre></details></div><div class="card"><h3>Casos de teste</h3><p class="note">Espaços extras entre valores e no final são ignorados na saída textual.</p><div id="test-results">${b.tests.map((t,i)=>`<details><summary>Caso ${i+1}</summary><p class="note">Entrada: ${esc(t.stdin||'(sem entrada)')}</p><p class="note">Saída esperada:</p>${pre(t.out||'(saída vazia)')}${t.inputFiles?`<p class="note">Arquivo inicial: ${esc(JSON.stringify(t.inputFiles))}</p>`:''}</details>`).join('')}</div></div><div class="card"><h3>Arquivos virtuais</h3><p class="note">Use / antes do nome. Os arquivos abaixo pertencem somente a esta execução.</p>${b.inputFiles?`<details><summary>Arquivos fornecidos neste exercício</summary>${Object.entries(b.inputFiles).map(([k,v])=>`<strong>/${esc(k)}</strong>${pre(v)}`).join('')}</details>`:''}<div id="virtual-files" class="note">Execute para ver arquivos criados ou alterados.</div></div></section></div>`;
$('#editor').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const el=e.target;el.setRangeText('    ',el.selectionStart,el.selectionEnd,'end');saveDraft();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();runLab(false);}});
$('#solution').addEventListener('toggle',()=>{if($('#solution').open){S.labs[b.id]={...S.labs[b.id],assisted:true};save();}});
}
function saveDraft(){if(activeLab&&$('#editor')){S.drafts[activeLab.id]={code:$('#editor').value,stdin:$('#stdin').value};save();}}
function runOne(code,stdin,files){return new Promise((resolve,reject)=>{if(!worker)worker=new Worker('compiler.js',{type:'module'});const id=Date.now()+Math.random();pending={id,resolve,reject};clearTimeout(workerTimer);workerTimer=setTimeout(()=>cancelRun('O carregamento demorou demais. Confira a internet e tente novamente.'),120000);
worker.onmessage=({data:d})=>{if(d.type==='status'){if($('#run-status'))$('#run-status').textContent=d.text;if(d.text==='Executando…'){clearTimeout(workerTimer);workerTimer=setTimeout(()=>cancelRun('Execução interrompida após 10 segundos. Verifique se seu laço termina.'),10000);}return;}if(d.id===pending?.id){clearTimeout(workerTimer);pending=null;resolve(d);}};
worker.onerror=e=>{clearTimeout(workerTimer);pending=null;worker?.terminate();worker=null;reject(Error(e.message||'O compilador não pôde iniciar. Verifique a conexão.'));};worker.postMessage({id,code,stdin:stdin.endsWith('\n')?stdin:stdin+'\n',files});});}
function cancelRun(message='Execução interrompida por você.'){worker?.terminate();worker=null;clearTimeout(workerTimer);pending?.reject(Error(message));pending=null;runBusy=false;}
const norm=s=>String(s??'').trim().replace(/\s+/g,' ');
function compilerHint(s){if(/undeclared identifier/.test(s))return 'Uma variável foi usada sem declaração ou com nome diferente. Confira maiúsculas, minúsculas e o escopo.';if(/expected.*[;}]/.test(s))return 'Confira os pontos e vírgulas, as chaves e a linha imediatamente anterior ao erro.';if(/incompatible.*pointer|integer to pointer/.test(s))return 'Há uma diferença entre valor e endereço. Confira &, * e os tipos dos parâmetros.';if(/implicit declaration/.test(s))return 'O compilador não conhece uma função. Confira o cabeçalho, o protótipo e o nome.';if(/undefined symbol/.test(s))return 'Uma função foi declarada ou chamada, mas sua implementação não foi encontrada.';if(/format specifies/.test(s))return 'Confira os especificadores: scanf usa %f para float* e %lf para double*; inteiros usam %d.';if(/out of bounds|unreachable/.test(s))return 'A execução acessou uma região inválida ou falhou. Confira os índices, a inicialização dos ponteiros e a condição de parada.';return 'Leia a primeira mensagem: ela costuma apontar a origem dos erros seguintes.';}
function displayRun(r){$('#stdout').textContent=r.stdout||'';$('#exit-code').textContent=r.exitCode===undefined?'Falha no ambiente':'Retorno: '+r.exitCode;$('#stderr').textContent=r.stderr||'';$('#diagnostics').hidden=!r.stderr;$('#diagnostics').open=!r.ok;$('#compiler-help').innerHTML=r.ok?'':`<div class="callout error"><strong>Revise a ${esc(r.phase||'execução')}</strong><p>${esc(compilerHint(r.stderr||''))}</p></div>`;$('#virtual-files').innerHTML=Object.entries(r.files||{}).filter(([p])=>p!=='/.runno').map(([p,f])=>`<details><summary>${esc(p)} · ${f.size} bytes</summary>${p.endsWith('.bin')?`<p class="note">Visualização hexadecimal (até 256 bytes)</p>${pre(f.hex)}`:pre(f.text)}</details>`).join('')||'Nenhum arquivo de usuário nesta execução.';}
async function runLab(tests){if(runBusy){toast('Espere a execução terminar ou use Parar.');return;}saveDraft();runBusy=true;const b=activeLab,code=$('#editor').value,input=$('#stdin').value;const buttons=[...main.querySelectorAll('[data-action="run"],[data-action="test"]')];buttons.forEach(b=>b.disabled=true);try{if(!tests){const r=await runOne(code,input,b.inputFiles||{});if(activeLab?.id===b.id&&$('#stdout')){displayRun(r);$('#run-status').textContent=r.ok?'Execução concluída':'Confira a mensagem abaixo';}}else{let passed=0;$('#test-results').innerHTML='Verificando…';const rows=[];for(let i=0;i<b.tests.length;i++){const t=b.tests[i],r=await runOne(code,t.stdin,t.inputFiles||b.inputFiles||{});let ok=r.ok&&norm(r.stdout)===norm(t.out);const fileChecks=[];for(const [p,v]of Object.entries(t.files||{})){const good=norm(r.files?.[p]?.text)===norm(v)&&!!r.files?.[p];fileChecks.push(`${p}: ${good?'correto':'diferente ou ausente'}`);ok=ok&&good;}if(t.exists){const good=!!r.files?.[t.exists]?.size;ok=ok&&good;fileChecks.push(`${t.exists}: ${good?'criado':'ausente ou vazio'}`);}if(ok)passed++;rows.push(`<div class="test-line"><strong class="${ok?'pass':'fail'}">${ok?'✓':'×'} Caso ${i+1}: ${ok?'passou':'rever'}</strong>${ok?'':`<p class="note">Esperado: ${esc(t.out||'(vazio)')}</p><p class="note">Obtido: ${esc(r.stdout||'(vazio)')}</p>`}${fileChecks.map(c=>`<div class="note">${esc(c)}</div>`).join('')}</div>`);if($('#test-results')){$('#test-results').innerHTML=rows.join('');displayRun(r);}}
S.labs[b.id]={...S.labs[b.id],passed:passed===b.tests.length,lastTests:passed,total:b.tests.length,date:Date.now()};save();if($('#run-status'))$('#run-status').textContent=`${passed}/${b.tests.length} testes aprovados`;if(passed===b.tests.length)toast('Todos os casos passaram! Confira também os critérios de lógica.');}
}catch(e){if($('#run-status'))$('#run-status').textContent=e.message;if($('#compiler-help'))$('#compiler-help').innerHTML=`<div class="callout error">${esc(e.message)}</div>`;}finally{runBusy=false;buttons.forEach(b=>b.disabled=false);}}
let filter='todos';
function training(){const pool=filter==='todos'?Q:Q.filter(q=>q.topic===filter);main.innerHTML=heading('PRÁTICA COM FEEDBACK','Treine o raciocínio, não o gabarito.','Selecione uma alternativa, confira o motivo e tente explicar o conceito com suas palavras. Cada erro entra no seu caderno de revisão.')+`<div class="filters">${['todos',...Object.keys(TOPICS)].map(t=>`<button class="chip ${filter===t?'active':''}" data-action="filter" data-arg="${t}">${TOPICS[t]||'Todos os temas'}</button>`).join('')}</div><div class="row" style="margin-bottom:24px">${btn('Treino de 10 questões →','start','practice:'+filter,'primary')}${btn('Revisar meus erros','start','errors')}${tag(pool.length+' QUESTÕES')}</div><div class="card">${pool.map((q,i)=>`<div class="course-row"><span class="course-number">${S.answers[q.id]?(S.answers[q.id].correct?'✓':'↻'):String(i+1).padStart(2,'0')}</span><div><h3>${esc(q.title)}</h3><p>${TOPICS[q.topic]} · ${esc(q.difficulty)} · PDF p. ${q.page}${q.exam?' · Adaptada do simulado do PDF':''}</p></div>${btn('Tentar','single',q.id,'small')}</div>`).join('')}</div>`;}
function startSession(kind){if(S.session&&!S.session.finished&&S.session.mode==='exam'){toast('Há um simulado em andamento. Finalize-o antes de iniciar outra sessão.');go('sessao');return;}let qs,mode='train',title='Treino de questões',duration=0;
if(kind==='diagnostic'){qs=Object.keys(TOPICS).map(t=>random(Q.filter(q=>q.topic===t&&!q.exam))[0]);qs=[...qs,...random(Q.filter(q=>!qs.includes(q)&&!q.exam)).slice(0,4)];title='Diagnóstico inicial';mode='exam';duration=20*60;}
else if(kind==='pdf1'||kind==='pdf2'){qs=Q.filter(q=>q.exam===kind);title='Simulado '+(kind==='pdf1'?'1':'2')+' · Objetivas do PDF';mode='exam';duration=25*60;}
else if(kind==='mixed'){qs=random(Q).slice(0,30);title='Simulado misto · 30 questões';mode='exam';duration=50*60;}
else if(kind==='errors'){qs=random(Q.filter(q=>S.errors[q.id]));title='Revisão dos erros';}
else if(kind.startsWith('single:'))qs=Q.filter(q=>q.id===kind.slice(7));
else{const topic=kind.split(':')[1]||'todos';qs=random(Q.filter(q=>topic==='todos'||q.topic===topic)).slice(0,10);title='Treino · '+(TOPICS[topic]||'Todos os temas');}
if(!qs.length){toast('Não há erros pendentes. Faça um treino para testar seu conhecimento.');return;}
S.session={ids:qs.map(q=>q.id),index:0,answers:{},checked:{},mode,title,started:Date.now(),duration,finished:false};save();go('sessao');}
function recordAnswer(q,choice){const correct=choice===q.answer;S.answers[q.id]={correct,choice,attempts:(S.answers[q.id]?.attempts||0)+1,date:Date.now()};if(correct)delete S.errors[q.id];else S.errors[q.id]={choice,date:Date.now()};}
function feedback(q,choice){const ok=choice===q.answer;return `<div class="callout ${ok?'success':'error'}" role="status"><strong>${ok?'✓ Boa! O raciocínio é este:':'Vamos corrigir o raciocínio.'}</strong><p>${esc(q.explanation)}</p>${!ok&&choice!==undefined?`<p><strong>Sobre sua alternativa:</strong> ${esc(q.wrong[choice]||'Confira a explicação do gabarito.')}</p>`:''}<p class="note">Resposta: ${String.fromCharCode(65+q.answer)} · ${esc(q.options[q.answer])} · Referência: PDF p. ${q.page}</p></div><details><summary>Entender as outras alternativas</summary>${q.options.map((o,i)=>`<p><strong>${String.fromCharCode(65+i)}.</strong> ${esc(i===q.answer?'Correta. '+q.explanation:q.wrong[i])}</p>`).join('')}</details>`;}
function sessionView(){const s=S.session;if(!s){go('treino');return;}if(s.finished){sessionResults();return;}const q=Q.find(q=>q.id===s.ids[s.index]),choice=s.answers[q.id],checked=!!s.checked[q.id];main.innerHTML=`<div class="question-box"><div class="row between"><span class="eyebrow muted">${esc(s.title)}</span>${s.mode==='exam'?'<span class="countdown" id="timer" aria-label="Tempo restante"></span>':tag('FEEDBACK IMEDIATO')}</div><div class="progress"><span style="width:${pct(s.index+1,s.ids.length)}%"></span></div><div class="row between" style="margin:20px 0">${tag(TOPICS[q.topic])}<span class="note">Questão ${s.index+1} de ${s.ids.length}</span></div><h2>${esc(q.title)}</h2>${q.code?pre(q.code):''}<div class="question-options" role="group" aria-label="Alternativas">${q.options.map((o,i)=>`<button class="option ${choice===i?'selected':''} ${checked?(i===q.answer?'correct':(choice===i?'wrong':'')):''}" data-action="answer" data-arg="${i}" aria-pressed="${choice===i}" ${checked?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>${checked?feedback(q,choice):''}<div class="row between"><div class="row">${btn('← Anterior','qprev','','ghost')}${s.mode==='train'&&!checked?btn('Conferir resposta','check','','primary'):''}${s.index<s.ids.length-1?btn('Próxima →','qnext','','primary'):btn(s.mode==='exam'?'Finalizar simulado':'Ver resultado','finish','','primary')}</div>${s.mode==='exam'?btn('Finalizar agora','finish','','ghost'):''}</div><div class="question-nav" aria-label="Ir para questão">${s.ids.map((id,i)=>`<button class="${i===s.index?'current':''} ${s.answers[id]!==undefined?'done':''}" data-action="qjump" data-arg="${i}" aria-label="Questão ${i+1}${s.answers[id]!==undefined?', respondida':''}">${i+1}</button>`).join('')}</div><p class="note">${s.mode==='exam'?'O gabarito aparece ao finalizar. O relógio continua se você sair desta página. Questões em branco contam como erro.':'Você pode pular questões. Somente respostas conferidas entram no seu histórico de treino.'}</p></div>`;updateTimer();}
function finish(){const s=S.session;if(!s||s.finished)return;if(s.mode==='exam'){s.ids.forEach(id=>{const q=Q.find(q=>q.id===id);recordAnswer(q,s.answers[id]);s.checked[id]=true;});}s.finished=true;s.ended=Date.now();const n=s.ids.filter(id=>s.checked[id]&&s.answers[id]===Q.find(q=>q.id===id).answer).length;S.history.unshift({title:s.title,right:n,total:s.ids.length,date:Date.now(),mode:s.mode});S.history=S.history.slice(0,30);save();sessionResults();}
function sessionResults(){const s=S.session,qs=s.ids.map(id=>Q.find(q=>q.id===id)),right=qs.filter(q=>s.checked[q.id]&&s.answers[q.id]===q.answer).length;main.innerHTML=heading('RESULTADO DA SESSÃO',esc(s.title),'Use o resultado para escolher o que revisar. O importante agora é entender por que cada resposta funciona.')+`<div class="grid two"><section class="card"><div class="score">${right}<span class="muted" style="font-size:30px"> / ${qs.length}</span></div><p>${pct(right,qs.length)}% de acertos · ${Math.max(1,Math.round(((s.ended||Date.now())-s.started)/60000))} min de sessão</p><div class="row">${btn('Revisar erros pendentes','start','errors','primary')}${link('Voltar aos simulados','simulados')}</div></section><section class="card"><h3>Direcione a revisão</h3>${Object.entries(TOPICS).filter(([id])=>qs.some(q=>q.topic===id)).map(([id,label])=>{const pool=qs.filter(q=>q.topic===id),n=pool.filter(q=>s.checked[q.id]&&s.answers[q.id]===q.answer).length;return `<div class="row between"><span>${label}</span><strong>${n}/${pool.length}</strong></div>`;}).join('')}</section></div><h2 class="section-heading">Correção comentada</h2>${qs.map((q,i)=>`<section class="card" style="margin-bottom:18px"><span class="note">Questão ${i+1} · ${TOPICS[q.topic]}</span><h3>${esc(q.title)}</h3>${q.code?pre(q.code):''}<p class="note">Sua resposta: ${s.answers[q.id]===undefined?'Em branco':String.fromCharCode(65+s.answers[q.id])}${!s.checked[q.id]?' · Não conferida no treino':''}</p>${feedback(q,s.answers[q.id])}${btn('Rever o assunto','topic',q.topic,'small')}</section>`).join('')}`;}
function updateTimer(){const s=S.session;if(!s||s.finished||s.mode!=='exam')return;const left=Math.max(0,s.duration-Math.floor((Date.now()-s.started)/1000));if($('#timer'))$('#timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left===0){finish();toast('Tempo encerrado. Seu simulado foi corrigido.');}}
setInterval(updateTimer,1000);
function exams(){main.innerHTML=heading('TREINE A SITUAÇÃO DE PROVA','Uma tentativa. Depois, a explicação.','Responda sem consultar as aulas. Os simulados 1 e 2 adaptam as 20 questões objetivas do PDF; as quatro dissertativas estão no laboratório.')+`${S.session&&!S.session.finished?`<div class="callout"><strong>Há uma sessão em andamento.</strong><div class="row">${link('Retomar sessão →','sessao','primary')}</div></div>`:''}<div class="grid">${[['pdf1','Simulado 1','10 objetivas · 25 minutos','Ponteiros, funções, arquivos, vetores e estruturas. PDF pp. 67–70.'],['pdf2','Simulado 2','10 objetivas · 25 minutos','Uma segunda rodada para testar os conceitos. PDF pp. 71–73.'],['mixed','Simulado misto','30 questões · 50 minutos','Questões sorteadas do banco completo, incluindo a base da NP1.']].map(([id,title,meta,desc])=>`<section class="card">${tag(meta)}<h2 style="margin-top:18px">${title}</h2><p>${desc}</p>${btn('Começar →','start',id,'primary')}</section>`).join('')}</div><section class="card" style="margin-top:24px"><h2>Complete com as dissertativas</h2><p>Reserve mais 30–45 minutos para escrever os programas sem consultar a solução. Os testes avaliam o funcionamento; os critérios do exercício ajudam a revisar a técnica.</p><div class="row">${['swap','binario','fatorial','media-vetor'].map(id=>link(esc(B.find(b=>b.id===id).title.slice(5)),'laboratorio/'+id,'small')).join('')}</div></section>${S.history.length?`<h2 class="section-heading">Histórico de sessões</h2><div class="card"><div class="table-wrap"><table><thead><tr><th>Sessão</th><th>Acertos</th><th>Data</th></tr></thead><tbody>${S.history.map(h=>`<tr><td>${esc(h.title)}</td><td>${h.right}/${h.total}</td><td>${new Date(h.date).toLocaleDateString('pt-BR')}</td></tr>`).join('')}</tbody></table></div></div>`:''}`;}
let cardIndex=0,cardReveal=false;
function review(){const errors=Q.filter(q=>S.errors[q.id]),due=L.filter(l=>!S.cards[l.id]||S.cards[l.id].due<=Date.now());const cards=due.length?due:L;cardIndex%=cards.length;const c=cards[cardIndex];main.innerHTML=heading('RELEMBRAR É APRENDER','Revisão ativa e caderno de erros','Antes de revelar uma resposta, tente recuperá-la da memória. A avaliação dos cartões é feita por você.')+`<div class="grid two"><section class="card"><h2>${errors.length} erros para revisar</h2><p>Uma resposta correta em uma nova tentativa retira a questão desta lista.</p>${btn('Treinar meus erros →','start','errors','primary')}</section><section class="card"><h2>${due.length} cartões disponíveis hoje</h2><p>“Ainda não” mantém o cartão para agora. “Lembrei” agenda para amanhã; “Fácil”, para daqui a três dias. Tudo fica neste navegador.</p></section></div><h2 class="section-heading">Recupere da memória</h2><section class="card flashcard"><div class="row between"><span class="tag">${TOPICS[c.topic]}</span><span class="note">${cardIndex+1} / ${cards.length}${!due.length?' · Revisão livre':''}</span></div><h2 style="margin:30px 0">${esc(c.recall.prompt)}</h2>${cardReveal?`<p class="answer">${esc(c.recall.answer)}</p><div class="row">${btn('Ainda não','cardRate',c.id+':0')}${btn('Lembrei','cardRate',c.id+':1','primary')}${btn('Fácil','cardRate',c.id+':3')}</div>`:btn('Revelar resposta','cardReveal','','primary')}<div class="row" style="margin-top:20px">${btn('← Anterior','cardPrev','','ghost')}${btn('Próximo →','cardNext','','ghost')}</div></section><h2 class="section-heading">Seu caderno de erros</h2>${errors.length?`<div class="stack">${errors.map(q=>`<section class="card"><span class="tag">${TOPICS[q.topic]}</span><h3 style="margin-top:14px">${esc(q.title)}</h3><p>${esc(q.explanation)}</p><div class="row">${btn('Tentar de novo','single',q.id,'small primary')}${link('Rever aula','trilha/'+(L.find(l=>l.topic===q.topic)?.id||L[0].id),'small')}</div></section>`).join('')}</div>`:'<div class="card empty">Nenhum erro pendente. Continue praticando para testar outros conceitos.</div>'}`;}
let viz='ponteiros',mem=[10,20,30,40,50],pi=0,swapStep=0,recN=4,recStep=0,matrixIndex=0,fileState=null;
function visuals(){main.innerHTML=heading('VEJA O PROGRAMA ACONTECER','Torne o raciocínio visível.','As visualizações abaixo são modelos didáticos. O laboratório executa seus programas reais.')+`<div class="filters">${[['ponteiros','Memória e ponteiros'],['swap','Troca passo a passo'],['recursao','Pilha da recursão'],['arquivos','Modos de arquivo'],['matriz','Matriz na memória'],['mesa','Teste de mesa']].map(([id,label])=>`<button class="chip ${viz===id?'active':''}" data-action="viz" data-arg="${id}">${label}</button>`).join('')}</div><div id="viz-area"></div>`;renderViz();}
function renderViz(){const a=$('#viz-area');if(!a)return;
if(viz==='ponteiros'){a.innerHTML=`<section class="card"><div class="row between"><h2>Endereço e conteúdo são coisas diferentes</h2>${tag('ENDEREÇOS FICTÍCIOS · int = 4 bytes')}</div>${pre('int v[5] = {10,20,30,40,50};\nint *p = v;')}<div class="memory-grid">${mem.map((n,i)=>`<div class="cell ${pi===i?'selected':''}"><small>v[${i}] · ${1000+i*4}</small><b>${n}</b><div class="pointer-arrow">${pi===i?'↑ p aponta aqui':'&nbsp;'}</div></div>`).join('')}</div><div class="callout" aria-live="polite"><strong>p = ${1000+pi*4}${pi===5?' (um após o fim)':''} · ${pi<5?'*p = '+mem[pi]:'*p não pode ser acessado'}</strong><p>${pi<5?'p++ avança para o próximo elemento. (*p)++ aumenta o valor do elemento atual.':'Esse endereço pode ser formado, mas desreferenciá-lo seria comportamento indefinido.'}</p></div><div class="row"><button class="btn" data-action="pdec" ${pi===0?'disabled':''}>p--</button><button class="btn primary" data-action="pinc" ${pi===5?'disabled':''}>p++</button><button class="btn" data-action="vinc" ${pi===5?'disabled':''}>(*p)++</button>${btn('Reiniciar','preset','','ghost')}</div><p class="note" style="margin-top:18px">No seu computador, os endereços variam. O avanço real é sizeof(int), e não necessariamente 4 em todas as implementações.</p></section>`;}
if(viz==='swap'){const rows=[[100,200,'—'],[100,200,100],[200,200,100],[200,100,100]],r=rows[swapStep];a.innerHTML=`<section class="card"><h2>Uma cópia temporária evita perder o primeiro valor</h2><div class="grid two"><pre>${['// a aponta para x; b aponta para y','int temp = *a;','*a = *b;','*b = temp;'].map((x,i)=>`<span class="trace-line ${i===swapStep?'current':''}">${esc(x)}</span>`).join('')}</pre><div><div class="memory-grid" style="grid-template-columns:repeat(3,1fr)">${['x (*a)','y (*b)','temp'].map((name,i)=>`<div class="cell"><small>${name}</small><b>${r[i]}</b></div>`).join('')}</div><p aria-live="polite">${['Estado inicial: os ponteiros recebidos são cópias dos endereços de x e y.','temp preserva 100, o conteúdo original de x.','x recebe 200. Agora x e y têm o mesmo valor, mas temp ainda guarda 100.','y recebe temp. A troca terminou: x = 200 e y = 100.'][swapStep]}</p></div></div><div class="row">${btn('← Voltar','swapBack')}${btn(swapStep===3?'Recomeçar':'Executar próxima linha →','swapNext','','primary')}</div></section>`;}
if(viz==='recursao'){const n=recN,steps=[];for(let k=n;k>=Math.min(1,n);k--)steps.push({call:k,phase:'chamada'});for(let k=Math.min(1,n);k<=n;k++)steps.push({call:k,phase:'retorno'});recStep=Math.min(recStep,steps.length-1);const st=steps[recStep];const fat=n=>n<=1?1:n*fat(n-1);a.innerHTML=`<section class="card"><div class="row between"><h2>Fatorial: primeiro as chamadas, depois os retornos</h2><label>n = <select id="rec-n">${[0,1,2,3,4,5,6].map(x=>`<option ${x===n?'selected':''}>${x}</option>`).join('')}</select></label></div>${pre('int fat(int n) {\n    if (n <= 1) return 1;\n    return n * fat(n - 1);\n}')}<div class="stack">${Array.from({length:Math.max(1,n)},(_,i)=>n-i).filter(k=>st.phase==='chamada'?k>=st.call:k>=st.call).map(k=>`<div class="row cell ${k===st.call?'selected':''}" style="text-align:left"><strong>fat(${k})</strong><span>${k<=1?'caso base → 1':st.phase==='retorno'&&k===st.call?`${k} × ${fat(k-1)} = ${fat(k)}`:`aguarda ${k} × fat(${k-1})`}</span></div>`).join('')}</div><div class="callout" aria-live="polite">${st.phase==='chamada'?`Entrando em fat(${st.call}). ${st.call<=1?'A condição de parada é verdadeira.':'A chamada atual precisa esperar a próxima.'}`:`fat(${st.call}) devolve ${fat(st.call)}.${st.call===n?' Resultado final disponível em main.':''}`}</div><div class="row">${btn('← Voltar','recBack')}${btn(recStep===steps.length-1?'Recomeçar':'Próximo passo →','recNext',String(steps.length),'primary')}</div></section>`;}
if(viz==='arquivos'){a.innerHTML=`<section class="card"><h2>O modo muda o destino dos seus dados</h2><div class="row"><label>Modo <select id="file-mode">${['r','w','a','r+','w+','a+','rb','wb','ab','r+b','w+b','a+b'].map(m=>`<option>${m}</option>`).join('')}</select></label><label class="check-row"><input id="file-exists" type="checkbox" checked> Arquivo já existe com ABC</label>${btn('Abrir arquivo','openFile','','primary')}</div><div id="file-sim" aria-live="polite"><p class="muted" style="margin-top:20px">Escolha um modo e abra o arquivo para observar o efeito.</p></div></section>`;fileState=null;}
if(viz==='matriz'){const row=Math.floor(matrixIndex/3),col=matrixIndex%3;a.innerHTML=`<section class="card"><h2>Linhas e colunas, memória contínua</h2><div class="grid two"><div><div class="matrix">${Array.from({length:9},(_,i)=>`<button class="${matrixIndex===i?'selected':''}" data-action="matrix" data-arg="${i}" aria-label="Selecionar m[${Math.floor(i/3)}][${i%3}]">${i+1}<br><small>m[${Math.floor(i/3)}][${i%3}]</small></button>`).join('')}</div></div><div class="callout" aria-live="polite"><h3>m[${row}][${col}] = ${matrixIndex+1}</h3><p>Deslocamento em elementos: ${row} × 3 + ${col} = ${matrixIndex}</p><p>Com int de 4 bytes e início fictício 1000:<br>1000 + ${matrixIndex} × 4 = <strong>${1000+matrixIndex*4}</strong></p><p class="note">Em C, a ordem é linha por linha. O próximo elemento após m[0][2] é m[1][0]. Use índices válidos para cada dimensão.</p></div></div><h3 style="margin-top:22px">Ordem física dos elementos</h3><div class="row">${Array.from({length:9},(_,i)=>`<span class="tag ${i!==matrixIndex?'plain':''}">${i+1}${i<8?' →':''}</span>`).join('')}</div></section>`;}
if(viz==='mesa'){a.innerHTML=`<section class="card"><h2>Execute com lápis e papel — ou digite aqui</h2>${pre('int soma = 0;\nfor (int i = 0; i < 3; i++) {\n    soma += i + 1;\n    printf("%d ", soma);\n}')}<p>Preencha os valores <strong>depois de soma += i + 1</strong>, em cada iteração.</p><div class="table-wrap"><table><thead><tr><th>Iteração</th><th>i</th><th>soma</th><th>Valor impresso</th></tr></thead><tbody>${[0,1,2].map((i)=>`<tr><td>${i+1}</td>${['i','soma','saida'].map(k=>`<td><input type="number" id="mesa-${i}-${k}" aria-label="${k}, iteração ${i+1}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="row" style="margin-top:20px">${btn('Conferir tabela','checkMesa','','primary')}</div><div id="mesa-result" aria-live="polite"></div></section>`;}}
function openFile(){const mode=$('#file-mode').value,exists=$('#file-exists').checked,base=mode[0],read=base==='r'||mode.includes('+'),write=base!=='r'||mode.includes('+');fileState={mode,read,write,content:base==='w'?'':exists?'ABC':'',pos:0,failed:base==='r'&&!exists};const f=fileState;$('#file-sim').innerHTML=f.failed?'<div class="callout error"><strong>fopen retorna NULL</strong><p>Os modos r e r+ (incluindo variantes b) exigem um arquivo existente.</p></div>':`<div class="callout"><strong>Arquivo aberto em ${mode}</strong><p>${base==='w'?'O conteúdo anterior foi apagado.':base==='a'?'O conteúdo anterior foi preservado; todas as escritas vão ao fim.':'O conteúdo anterior foi preservado; a posição inicial é o começo.'}</p><p>Leitura: ${read?'sim':'não'} · Escrita: ${write?'sim':'não'} · ${mode.includes('b')?'Binário':'Texto'}</p><p class="note">${mode.includes('+')?'O + habilita leitura e escrita. Ao alternar operações, respeite as regras de posicionamento/flush do C.':''}</p></div><strong>Conteúdo após a abertura</strong><pre id="file-content">${esc(f.content||'(vazio)')}</pre>${btn('Escrever XY','writeFile','','primary')}<p class="note" style="margin-top:12px">Modelo didático de abertura e escrita; não representa o buffer. A letra b não muda as permissões.</p>`;}
function writeFile(){const f=fileState;if(!f||f.failed)return;if(!f.write){toast('Esse modo só permite leitura.');return;}if(f.mode[0]==='a')f.content+='XY';else{f.content=f.content.slice(0,f.pos)+'XY'+f.content.slice(f.pos+2);f.pos+=2;}$('#file-content').textContent=f.content;}
const planUnits=[['Entender ponteiros','Leia as aulas de ponteiros, explore a memória e resolva os desafios 1 e 2.','ponteiros'],['Usar endereços em funções','Pratique Volume, aritmética de ponteiros e funções com protótipo.','ponteiros'],['Dominar funções e recursão','Estude escopo, passagem de argumentos e a pilha de fat(4). Faça os desafios 5 e 6.','funcoes'],['Organizar dados','Revise vetores, strings, matrizes e structs. Faça os desafios 7 a 13.','vetores'],['Persistir dados em arquivos','Estude modos, EOF, texto e binário. Faça os desafios 14 a 17.','arquivos'],['Integrar e simular','Revise a base NP1. Faça o desafio integrador e o Simulado 1, incluindo as dissertativas.','np1'],['Revisar os erros e testar de novo','Retome questões erradas, faça o Simulado 2 e explique os conceitos sem consultar.','arquivos']];
function plan(){const days=S.days,units=Array.from({length:days},(_,i)=>({day:i+1,items:planUnits.filter((_,j)=>Math.floor(j*days/7)===i)}));if(days===14)units.forEach((u,i)=>{if(!u.items.length)u.items=[['Consolidação e recuperação','Refaça sem consulta os exercícios do dia anterior. Revise cartões e escreva uma explicação sobre o erro mais importante.','np1']];});main.innerHTML=heading('CONSISTÊNCIA ANTES DA PROVA','Um plano que cabe no seu prazo.','O plano organiza a cobertura do material. Ajuste o tempo à sua dificuldade e faça pausas; não há promessa de nota ou estimativa de domínio automático.')+`<div class="row" style="margin-bottom:24px"><label>Organizar em <select id="plan-days">${[3,7,14].map(n=>`<option value="${n}" ${days===n?'selected':''}>${n} dias</option>`).join('')}</select></label><span class="note">${days===3?'Ritmo intensivo: divida cada dia em várias sessões.':days===7?'Sugestão: 60–90 min por dia, ampliando os dias com mais desafios.':'Sugestão: 30–60 min por dia, alternando estudo e recuperação.'}</span></div><div class="grid two">${units.map(u=>`<section class="card"><div class="row between">${tag('DIA '+u.day)}<label class="check-row"><input type="checkbox" data-plan="${days}-${u.day}" ${S.plan[days+'-'+u.day]?'checked':''}> Concluído</label></div>${u.items.map(([title,desc])=>`<h3 style="margin-top:15px">${title}</h3><p>${desc}</p>`).join('')}<div class="row">${link('Abrir trilha','trilha','small')}${link('Praticar','laboratorio','small')}</div></section>`).join('')}</div><section class="card" style="margin-top:24px"><h2>Antes de considerar um assunto revisado</h2><ul><li>Consigo explicar sem olhar a definição?</li><li>Consigo prever a saída e justificar cada mudança de variável?</li><li>Consigo escrever uma solução do zero e testar casos diferentes?</li><li>Consigo dizer por que as alternativas erradas estão erradas?</li></ul></section>`;}
const corrections=[['Vetor não é um ponteiro constante','O PDF usa essa simplificação (pp. 35–36). Um array é um objeto com elementos; em muitas expressões ele é convertido em ponteiro para o primeiro elemento. sizeof(v) e &v são exemplos importantes em que essa conversão não ocorre.'],['Em C, argumentos são passados por valor','A “passagem por referência” do curso (pp. 41–43) é implementada copiando um endereço para um parâmetro ponteiro. Escrever em *p altera o objeto original; reatribuir o parâmetro p não altera o ponteiro do chamador.'],['Tamanhos e endereços dependem da implementação','As tabelas do PDF usam valores típicos (pp. 22, 34, 48). sizeof(char) é sempre 1; int, ponteiros e outros tipos podem variar. Nesta execução WebAssembly, ponteiros e int têm 4 bytes. Use %zu para sizeof e %p com conversão para void* para endereços.'],['Struct pode conter preenchimento','A soma dos tamanhos dos campos, citada nas pp. 28–30, pode ser menor que sizeof da estrutura por causa do alinhamento. Use sizeof(objeto) ou sizeof(Tipo). Um arquivo binário com a representação bruta da struct não é um formato universal entre máquinas.'],['EOF não é necessariamente -1','O padrão exige que EOF seja uma constante inteira negativa. Guarde fgetc em int para distinguir todos os valores de unsigned char de EOF. Controle a leitura pelo retorno de fscanf, fgets ou fread; feof só indica que o fim já foi encontrado.'],['Prefira int main(void), fgets e entrada validada','Exemplos antigos usam void main, gets e fflush(stdin). gets foi removida do C11; fflush(stdin) não é uma limpeza portátil do teclado. Use fgets, limites de leitura e testes de retorno. conio.h e system("pause") dependem do ambiente.'],['Índices e aritmética têm limites','p[-1] só é válido se apontar para um elemento existente do mesmo array. Não acesse antes do começo nem após o fim. Um ponteiro um após o fim pode ser formado, mas não desreferenciado. Comparações de ordem entre ponteiros de objetos separados não são uma regra geral válida.'],['Um resultado observado não torna código indefinido correto','Expressões como i++ + ++i têm modificações não sequenciadas e comportamento indefinido. Não tente decorar uma saída específica. Precedência organiza a expressão, mas não determina toda a ordem de avaliação.'],['Headers declaram; arquivos .c implementam','Não existe regra de uma função por .c nem de várias funções obrigatoriamente em .h/.lib (p.17). O usual é colocar protótipos no .h e implementar em .c, compilando e ligando os arquivos juntos.'],['Escopo e duração são conceitos diferentes','Uma variável local automática normalmente existe durante a execução do bloco. Uma local static mantém seu valor entre chamadas, embora o nome continue com escopo local. C11 também oferece _Bool e bool via stdbool.h.']];
function reference(){main.innerHTML=heading('UM APOIO PARA CONSULTAR','O essencial, sem perder a precisão.','As aulas e questões usam o PDF como base. Os ajustes abaixo distinguem a explicação simplificada do material do comportamento correto em C.')+`<div class="reference-grid"><section class="card"><h2>Ponteiros</h2>${pre('int *p = &x;   // endereço de x\n*p = 75;       // muda x\np++;           // próximo elemento\n(*p)++;        // aumenta o conteúdo\nv[i] == *(v+i) // elemento do vetor\nint *v[10];    // 10 ponteiros')}<p class="note">Sempre inicialize antes de desreferenciar e respeite os limites do objeto.</p></section><section class="card"><h2>Entrada e saída</h2><div class="table-wrap"><table><tr><th>Dado</th><th>scanf</th><th>printf</th></tr><tr><td>int x</td><td>"%d", &amp;x</td><td>"%d", x</td></tr><tr><td>float x</td><td>"%f", &amp;x</td><td>"%f", x</td></tr><tr><td>double x</td><td>"%lf", &amp;x</td><td>"%f", x</td></tr><tr><td>char c</td><td>" %c", &amp;c</td><td>"%c", c</td></tr><tr><td>char s[20]</td><td>"%19s", s</td><td>"%s", s</td></tr></table></div><p class="note" style="margin-top:12px">O espaço antes de %c pula espaços e novas linhas. fgets lê uma linha com limite e pode guardar o Enter.</p></section><section class="card"><h2>Modos de arquivo</h2><table><tr><th>Modo</th><th>Exige existir?</th><th>Conteúdo anterior</th></tr><tr><td>r / r+</td><td>Sim</td><td>Preserva</td></tr><tr><td>w / w+</td><td>Não</td><td>Apaga</td></tr><tr><td>a / a+</td><td>Não</td><td>Preserva; escreve no fim</td></tr></table><p class="note" style="margin-top:12px">+ permite ler e escrever. b indica modo binário. fopen retorna NULL na falha; fclose retorna 0 no sucesso. Em streams de atualização (+), respeite as regras de alternância entre entrada e saída.</p></section><section class="card"><h2>Escolha a função</h2><table><tr><th>Operação</th><th>Escrever</th><th>Ler</th></tr><tr><td>Texto formatado</td><td>fprintf</td><td>fscanf</td></tr><tr><td>Bytes / blocos</td><td>fwrite</td><td>fread</td></tr><tr><td>Caractere</td><td>fputc</td><td>fgetc</td></tr><tr><td>String / linha</td><td>fputs</td><td>fgets</td></tr></table>${pre('fwrite(&obj, sizeof obj, 1, f);\nwhile (fscanf(f, "%d", &x) == 1) {\n    /* use x */\n}')}</section><section class="card"><h2>Strings e organização</h2><p>char s[20] reserva 20 bytes. Uma string terminada em nulo usa um deles para '\\0'; cabem até 19 bytes úteis, não necessariamente 19 caracteres Unicode.</p>${pre('strcpy(destino, origem);\nstrcat(destino, origem);\nstrcmp(a,b) == 0; // conteúdo igual\ns[strcspn(s,"\\n")] = \'\\0\';')}<p class="note">O destino precisa ter capacidade suficiente. strlen não conta o terminador.</p></section><section class="card"><h2>Controle e precedência</h2><p>Use parênteses para deixar a intenção clara.</p>${pre('* / % antes de + -\n! antes de && antes de ||\n= atribui; == compara\na = i++; // usa valor antigo\na = ++i; // usa valor incrementado')}<p class="note">while e for podem executar zero vezes; do…while executa pelo menos uma vez quando o fluxo alcança o laço. break sai do laço ou switch mais interno. continue segue para a próxima iteração.</p></section></div><h2 class="section-heading">Ajustes importantes no material</h2><div class="card">${corrections.map(([title,text])=>`<details><summary>${title}</summary><p>${text}</p></details>`).join('')}</div><h2 class="section-heading">Fontes e funcionamento</h2><section class="card"><p><strong>Fonte principal:</strong> Material_Estudo_C_NP2.pdf, 76 páginas, enviado por você. Unidades 4, 5, 6 e 8 e revisão das unidades 1, 2 e 3. As páginas indicadas nas atividades são as páginas do PDF.</p><p>As aulas são uma adaptação didática. O banco inclui os dois simulados objetivos do PDF e questões complementares. As dissertativas foram convertidas em desafios executáveis. A ordem de estudo é uma sugestão pedagógica.</p><p><strong>Referência técnica:</strong> <a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noopener">rascunho público do padrão C11 (WG14 N1570)</a>. Seções 6.3.2.1 (arrays), 6.5 (expressões), 6.7.2.1 (structs), 6.5.2.2 (chamadas) e 7.21 (entrada/saída).</p><p><strong>Execução:</strong> compilador Clang para WebAssembly e biblioteca <a href="https://github.com/taybenlor/runno" target="_blank" rel="noopener">Runno</a>. <a href="vendor/LICENSE" target="_blank">Licença da biblioteca WASI</a>. O compilador é baixado de recursos públicos do projeto; seu código é executado localmente no navegador. O ambiente oferece C11 com biblioteca WASI, não um sistema operacional completo.</p><p class="note">Arquivos virtuais recomeçam a cada execução. Dados de estudo e rascunhos ficam no armazenamento deste navegador, sem sincronização entre dispositivos. Exportar um backup permite transferi-los.</p><div class="row">${btn('Exportar meu progresso','export','','primary')}<label class="btn">Importar backup<input type="file" id="import" accept="application/json,.json" hidden></label></div><div id="import-preview"></div></section>`;}
function exportData(){download('meu-progresso-np2.json',JSON.stringify(S,null,2),'application/json');}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let imported=null;
main.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,arg=el.dataset.arg;const s=S.session;
switch(action){case'lesson':go('trilha/'+arg);break;case'completeLesson':S.lessons[arg]=!S.lessons[arg];save();render();break;case'topic':filter=arg;go('treino');break;case'filter':filter=arg;training();break;case'start':startSession(arg);break;case'single':startSession('single:'+arg);break;case'answer':if(s){s.answers[s.ids[s.index]]=Number(arg);save();sessionView();}break;case'check':{const q=Q.find(q=>q.id===s.ids[s.index]);if(s.answers[q.id]===undefined){toast('Selecione uma alternativa primeiro.');break;}recordAnswer(q,s.answers[q.id]);s.checked[q.id]=true;save();sessionView();break;}case'qprev':s.index=Math.max(0,s.index-1);save();sessionView();break;case'qnext':s.index=Math.min(s.ids.length-1,s.index+1);save();sessionView();break;case'qjump':s.index=Number(arg);save();sessionView();break;case'finish':finish();break;case'run':runLab(false);break;case'test':runLab(true);break;case'stop':cancelRun();break;case'hint':{const box=$('#hints'),n=box.children.length;if(n<activeLab.hints.length)box.insertAdjacentHTML('beforeend',`<div class="callout"><strong>Dica ${n+1}</strong><p>${esc(activeLab.hints[n])}</p></div>`);else toast('Todas as dicas estão abertas. Confira os critérios ou a solução.');break;}case'useSolution':$('#editor').value=activeLab.solution;S.labs[activeLab.id]={...S.labs[activeLab.id],assisted:true};saveDraft();toast('Solução inserida. Execute e experimente mudar os dados.');break;case'restoreCode':if(!el.dataset.confirmed){el.dataset.confirmed='yes';el.textContent='Confirmar restauração';}else{$('#editor').value=activeLab.starter;saveDraft();el.textContent='Restaurar início';delete el.dataset.confirmed;}break;case'downloadCode':download(activeLab.id+'.c',$('#editor').value,'text/plain');break;case'cardReveal':cardReveal=true;review();break;case'cardNext':cardIndex++;cardReveal=false;review();break;case'cardPrev':cardIndex=Math.max(0,cardIndex-1);cardReveal=false;review();break;case'cardRate':{const [id,d]=arg.split(':');S.cards[id]={due:Date.now()+Number(d)*86400000};save();cardReveal=false;if(d==='0')cardIndex++;review();break;}case'viz':viz=arg;visuals();break;case'pinc':pi=Math.min(5,pi+1);renderViz();break;case'pdec':pi=Math.max(0,pi-1);renderViz();break;case'vinc':if(pi<5)mem[pi]++;renderViz();break;case'preset':mem=[10,20,30,40,50];pi=0;renderViz();break;case'swapBack':swapStep=Math.max(0,swapStep-1);renderViz();break;case'swapNext':swapStep=(swapStep+1)%4;renderViz();break;case'recBack':recStep=Math.max(0,recStep-1);renderViz();break;case'recNext':recStep=(recStep+1)%Number(arg);renderViz();break;case'matrix':matrixIndex=Number(arg);renderViz();break;case'openFile':openFile();break;case'writeFile':writeFile();break;case'checkMesa':{const expect=[[0,1,1],[1,3,3],[2,6,6]],keys=['i','soma','saida'];let n=0;expect.forEach((r,i)=>r.forEach((v,j)=>{const input=$('#mesa-'+i+'-'+keys[j]),ok=input.value.trim()!==''&&Number(input.value)===v;input.setAttribute('aria-invalid',!ok);input.style.borderColor=ok?'var(--accent)':'var(--error)';if(ok)n++;}));$('#mesa-result').innerHTML=`<div class="callout ${n===9?'success':'warn'}"><strong>${n} de 9 valores corretos.</strong><p>${n===9?'A soma acumula 1, depois 2, depois 3: a saída é 1 3 6.':'O acumulador não volta a zero. Após cada iteração: (i,soma,saída) = (0,1,1), (1,3,3), (2,6,6).'}</p></div>`;break;}case'export':exportData();break;case'importConfirm':if(imported){S={...empty(),...imported};imported=null;save();document.body.classList.toggle('dark',S.theme==='dark');toast('Progresso importado.');render();}break;}});
main.addEventListener('input',e=>{if(e.target.id==='editor'||e.target.id==='stdin')saveDraft();if(e.target.dataset.note){S.notes[e.target.dataset.note]=e.target.value;save();}});
main.addEventListener('change',async e=>{const el=e.target;if(el.id==='rec-n'){recN=Number(el.value);recStep=0;renderViz();}if(el.id==='plan-days'){S.days=Number(el.value);save();plan();}if(el.dataset.plan){S.plan[el.dataset.plan]=el.checked;save();}if(el.id==='import'){try{const file=el.files[0];if(!file)return;if(file.size>4000000)throw Error('Backup muito grande.');const data=JSON.parse(await file.text());if(data.version!==1||!data.answers||!data.drafts||!data.lessons||!Array.isArray(data.history))throw Error('Arquivo não reconhecido como backup deste estudo.');for(const key of ['lessons','answers','errors','labs','drafts','notes','cards','plan'])if(data[key]===null||typeof data[key]!=='object'||Array.isArray(data[key]))throw Error('Formato inválido em '+key);data.session=null;data.days=[3,7,14].includes(data.days)?data.days:7;data.theme=data.theme==='dark'?'dark':'light';imported=data;$('#import-preview').innerHTML=`<div class="callout warn"><p>Este backup contém ${Object.keys(data.answers).length} questões registradas. Importar substituirá o progresso atual deste navegador. Exporte o atual se quiser preservá-lo.</p>${btn('Confirmar importação','importConfirm','','primary')}</div>`;}catch(err){toast('Não foi possível importar: '+err.message);}}});
function render(){const [page='inicio',id]=location.hash.slice(1).split('/');if(runBusy){cancelRun('Execução interrompida ao trocar de página.');}document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===page||(page==='sessao'&&a.dataset.nav==='treino');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});switch(page){case'inicio':case'':dashboard();break;case'trilha':lessons(id);break;case'laboratorio':laboratory(id);break;case'treino':training();break;case'sessao':sessionView();break;case'simulados':exams();break;case'revisao':review();break;case'visualizar':visuals();break;case'plano':plan();break;case'referencia':reference();break;default:dashboard();}window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',render);save();render();
})();
